function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  noStroke();

  // Sky
  brush.fillBleed(0.45);
  brush.fillTexture(1.0, 100);
  brush.beginShape(0.5);
  vertex(200, 50);
  vertex(200, 400);
  vertex(200, 400);
  vertex(200, 100);
  endShape(true);

  // Hill
  brush.fillBleed(0.2);
  brush.fillTexture(0.3, 30);
  brush.beginShape(0.3);
  vertex(100, 60);
  vertex(300, 180);
  vertex(300, 450);
  vertex(100, 450);
  endShape(true);

  // Trees
  brush.fillTexture(0.6, 30);
  brush.fillBleed(0.45);
  brush.beginShape(0.3);
  vertex(60, 200);
  vertex(200, 300);
  vertex(60, 350);
  vertex(200, 450);
  endShape(true);

  // Grass
  brush.fillBleed(0.7);
  brush.fillTexture(1.0, 200);
  brush.beginShape(0.8);
  vertex(60, 450);
  vertex(200, 350);
  vertex(60, 300);
  vertex(200, 200);
  endShape(true);

  // Ground
  brush.fillTexture(0.95, 20);
  brush.fillBleed(0.4);
  brush.fillTexture(0.6, 60);
  brush.fillBleed(0.45);
  brush.beginShape(1.0);
  vertex(60, 450);
  vertex(200, 350);
  vertex(300, 180);
  vertex(200, 300);
  vertex(60, 100);
  endShape(true);
}
