function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#e08a72");
  let grassColor = "#98d971";
  let hills = 40;
  for (let hillIndex = 0; hillIndex < hills; hillIndex++) {
    if (hillIndex % 5 === 0) {
      grassColor = "#c4e292";
    } else {
      grassColor = "#b0c88d";
    }
    brush.fill(grassColor, 70);
    brush.circle(200 + hillIndex * 20, 170 + hillIndex * 10, 20 + hillIndex);
    brush.fill(grassColor, 70);
    brush.circle(200 + hillIndex * 20, 250 + hillIndex * 10, 20 + hillIndex);
  }
  fill("#e08a72");
  noStroke();
  for (let i = 0; i < hills; i++) {
    let angle = i * 2 * Math.PI / hills;
    let bend = (i * 2) % hills === 0 ? 0 : i % 4;
    brush.circle(200 + i * 20, 160 + i * 10, 20);
    brush.vertex(200 + i * 20, 170 + i * 10 + bend);
    brush.circle(200 + i * 20, 250 + i * 10, 20);
    brush.vertex(200 + i * 20, 250 + i * 10 + bend);
    brush.endShape();
  }
  fill("#b0c88d");
  noStroke();
  for (let i = 0; i < hills; i++) {
    brush.circle(200 + i * 20, 160 + i * 10, 20);
    brush.vertex(200 + i * 20, 250 + i * 10);
  }
  brush.endShape();
  brush.stroke(0);
}
