Here's how you could write a simple sunset using the p5.brush library:

```javascript
let hillsTexture = [
  "e07b38", "e07b38", "e07b38", 
  "e07b38", "e30f0f", "e30f0f",
  "e07b38", "e30f0f", "e07b38",
  "e07b38", "e30f0f", "e07b38",
]

function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  brush.fillTexture(1, 0);
  for (let i = 0; i < hillsTexture.length; i += 3) {
    brush.vertex((i / 3) * width, 0);
    brush.vertex((i / 3) * width, height);
    brush.vertex((i / 3) * width, height - 100);
    brush.endShape(true);
    brush.fillTexture(1, 1);
    brush.fill(1);
    brush.circle(i, height - 200, 50);
  }

  brush.fillBleed(0.4);
  brush.fill(149, 231, 130);
  brush.fillBleed(0.8);
  brush.vertex(200, 200);
  brush.vertex(200, 180);
  brush.vertex(200, 220);
  brush.endShape(true);
  brush.fillBleed(1.0);
}
