function setup() {
  createCanvas(400, 400, WEBGL)
  brush.scaleBrushes(2)
  noLoop()
}

function draw() {
  translate(-width / 2, -height / 2)
  background("#f4efe4")
  paintingSinking()

  loop()
}

function paintingSinking() {
  let groundCheck = (100, 100)
  if (brush.noStroke()) {
    brush.fillBleed(1.5)  // 0 to 1
    brush.fillTexture(1.5, 10)
    brush.circle(groundCheck[0], groundCheck[1], 20)
    groundCheck[0] = random(0, 400)
    groundCheck[1] = random(0, 400)
  } else if (brush.fill(noStroke())) {
    brush.fillTexture(1.2, 10)
    brush.circle(groundCheck[0], groundCheck[1], 20)
    groundCheck[0] = random(0, 400)
    groundCheck[1] = random(0, 400)
  }
}

function drawEye() {
  if (brush.beginShape()) {
    brush.vertex(35, 230)
    brush.vertex(180, 230)
    brush.vertex(35, 230)
    brush.endShape(true)
  }
}
