(function () {
  'use strict';
  const p5 = window.p5;

  let sketch = {
    creator: function () {
      return sketch;
    }
  };

  var middleView = sketch.lookup('middleView');
  var hillsHeight = 500;
  var hillHeight1 = 400;
  var hillHeight2 = 200;
  var hillWidth = 200;
  var topPartHeight = 200;

  function createMiddleView() {
    var r = Math.random();
    var scroll = Math.floor((Math.random() * hillsHeight) - 0.5);
    middleView = new MiddleView({
      hillHeight1: hillHeight1 * r,
      hillHeight2: hillHeight2 * r,
      hillWidth: hillWidth * r,
      topPartHeight: topPartHeight * r,
      scroll: scroll
    });
  }

  function lookup(func) {
    if (!sketch[func]) {
      createMiddleView();
    }
    return sketch[func];
  }

  function paintHills() {
    lookup('midVar');

    var shapeId = lookup('midVar').world.who;
    var catProgress = lookup('midVar').catProgress;
    var catVar = lookup('midVar').catVar;

    if (catProgress >= 200) {
      catVar = Math.max(200, Math.min(catVar + 2, 255));
    }
    if (catProgress < 0) {
      catVar = Math.max(-200, Math.min(catVar - 2, 255));
    }
    lookup('midVar').catProgress = catProgress + 0.25;

    if (shapeId == 'top') {
      var x = 200;
      for (var c = 200; c >= -200; c -= 10) {
        lookup('midVar').`cat0Var-${c}` = Math.floor((catVar + 10) * 0.5 + c);
      }
    } else {
      lookup('midVar').cat1Var = catVar;
    }
  }

  function draw() {
    p5.fillStyle(`#f4efe4`);
    p5.fillRect(0, 0, width, height);

    var yDiff = Math.floor((Math.random() * (300 + topPartHeight) - topPartHeight));
    lookup('midVar').topPartY = yDiff;
    lookup('midVar').topPartYAcc = 100;

    lookup('midVar').cat2Var = Math.floor(Math.random() * 300);
    lookup('midVar').topPartX = Math.floor(Math.random() * (400 - 100) * 2 + 50);

    paintHills();

    lookup('midVar').catVar -= 1;

